{
  "understanding": {
    "purpose": "按需求、开发和测试项目展示三个阶段的工作安排。",
    "reading": "先按行识别工作项目，再横向阅读各阶段；跨列说明代表相邻阶段共同承担的工作。长说明决定部分行高，较短内容的换行可利用这些行已有的高度。",
    "groups": [
      "阶段一、阶段二、阶段三是并列的时间阶段，应便于横向比较。",
      "阶段二同时参与两段交错的跨列说明，其宽度会影响两段文本的换行。"
    ],
    "keep_intact": [
      "尽量让“项目”“需求”“开发”“测试”保持一行。",
      "尽量让“用例”和“回归”保持一行，便于扫描。",
      "阶段表头尽量按相近节奏换行，避免逐字竖排。"
    ],
    "may_wrap": [
      "两段跨列长说明可自然换行，但应保持连续的文本块。",
      "“搭建脚手架”可分行，尽量避免逐字换行。",
      "阶段表头可换行，优先保持“阶段”作为一个词。"
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [55, 55, 44, 44],
      "idea": "优先保住项目名称以及阶段一中的两字短词，阶段二和阶段三则接受较窄的文字空间。"
    },
    {
      "name": "B",
      "widths": [39, 55, 55, 49],
      "idea": "把空间集中给阶段一和共享的阶段二，使短词更易读并改善两段跨列说明，代价是项目列逐字换行。"
    },
    {
      "name": "C",
      "widths": [45, 57, 48, 48],
      "idea": "略偏重阶段一，同时让后两个阶段保持相同宽度，以较均衡的阶段节奏换取项目列和后两列的较多换行。"
    }
  ]
}
